-- Verification
SELECT 'academic_catalog_sources' AS table_name, COUNT(*) AS row_count FROM academic_catalog_sources
UNION ALL
SELECT 'academic_catalogs', COUNT(*) FROM academic_catalogs
UNION ALL
SELECT 'academic_catalog_sync_runs', COUNT(*) FROM academic_catalog_sync_runs
UNION ALL
SELECT 'program_types', COUNT(*) FROM program_types
UNION ALL
SELECT 'departments', COUNT(*) FROM departments
UNION ALL
SELECT 'class_groups', COUNT(*) FROM class_groups;

SELECT id, `key`, current_catalog_id
FROM academic_catalog_sources
ORDER BY id;

SELECT id, version, status, program_count, department_count,
       class_group_count, selectable_class_group_count
FROM academic_catalogs
ORDER BY id;

SELECT
  COUNT(*) AS total_classes,
  SUM(is_registration_selectable = 1) AS selectable_classes,
  MIN(grade_no) AS min_grade,
  MAX(grade_no) AS max_grade
FROM class_groups;
